import { Kbd } from "@/registry/erbium/ui/kbd";

const KbdDemo = () => (
  <div className="flex flex-wrap items-center justify-center gap-related">
    <Kbd hotkey="Mod+Shift+K" />
    <Kbd hotkey="Mod+B" />
    <Kbd hotkey="Escape" />
  </div>
);

export default KbdDemo;

import { Icon } from "@/registry/erbium/ui/icon";

import { InputGroup, InputGroupAddon, InputGroupInput } from "@/registry/erbium/ui/input-group";
import { Kbd } from "@/registry/erbium/ui/kbd";

const KbdInputGroup = () => (
  <div className="flex w-full max-w-xs flex-col gap-section">
    <InputGroup>
      <InputGroupInput placeholder="Search..." />
      <InputGroupAddon>
        <Icon name="search-01" />
      </InputGroupAddon>
      <InputGroupAddon align="inline-end">
        <Kbd hotkey="Mod+K" />
      </InputGroupAddon>
    </InputGroup>
  </div>
);

export default KbdInputGroup;

import { Button } from "@/registry/erbium/ui/button";
import { ButtonGroup } from "@/registry/erbium/ui/button-group";
import { Kbd } from "@/registry/erbium/ui/kbd";
import { Tooltip, TooltipContent, TooltipTrigger } from "@/registry/erbium/ui/tooltip";

const KbdTooltip = () => (
  <div className="flex flex-wrap gap-group">
    <ButtonGroup>
      <Tooltip>
        <TooltipTrigger
          render={
            <Button size="sm" variant="outline">
              Save
            </Button>
          }
        />
        <TooltipContent>
          Save Changes <Kbd hotkey="S" />
        </TooltipContent>
      </Tooltip>
      <Tooltip>
        <TooltipTrigger
          render={
            <Button size="sm" variant="outline">
              Print
            </Button>
          }
        />
        <TooltipContent>
          Print Document <Kbd hotkey="Mod+P" />
        </TooltipContent>
      </Tooltip>
    </ButtonGroup>
  </div>
);

export default KbdTooltip;

