const PlaygroundSource = "import { Kbd } from \"@/registry/erbium/ui/kbd\";\nimport type * as React from \"react\";\n\nconst Example = (args: React.ComponentProps<typeof Kbd>) => <Kbd {...args} />;\n\nexport default Example;\n";

