import TooltipExample from "./variants/tooltip";

const TooltipSource = "import ExampleKbdTooltip from \"../examples/kbd-tooltip\";\n\nconst Example = () => (\n  <div className=\"w-full min-w-72 max-w-2xl p-4\">\n    <ExampleKbdTooltip />\n  </div>\n);\n\nexport default Example;\n";

import InputGroupExample from "./variants/input-group";

const InputGroupSource = "import ExampleKbdInputGroup from \"../examples/kbd-input-group\";\n\nconst Example = () => (\n  <div className=\"w-full min-w-72 max-w-2xl p-4\">\n    <ExampleKbdInputGroup />\n  </div>\n);\n\nexport default Example;\n";

const meta = {
  component: Kbd,
  parameters: {
    docs: {
      description: {
        component: "## Usage\n\nDisplays a platform-aware shortcut. Pass the stored binding to `hotkey`; TanStack Hotkeys formats it for macOS, Windows, or Linux.\n\n**Import:** `@/registry/erbium/ui/kbd`\n\n```tsx\n<Kbd hotkey=\"Mod+K\" />\n```\n\n## Registering shortcuts\n\n`Kbd` only renders a binding; it does not register one. Register the behavior with `useHotkey` from `@tanstack/react-hotkeys` and display the same binding with `Kbd`, so the label and the shortcut never drift apart.\n\n```tsx\nimport { useHotkey } from \"@tanstack/react-hotkeys\";\nimport { Kbd } from \"@/registry/erbium/ui/kbd\";\n\nexport function SaveButton() {\n  useHotkey(\"Mod+S\", () => save());\n  return (\n    <button type=\"button\" onClick={save}>\n      Save <Kbd hotkey=\"Mod+S\" />\n    </button>\n  );\n}\n```\n\nComponents that ship shortcuts register them the same way: `SidebarProvider` toggles with `Mod+B`, and command palettes register `Mod+K` with `useHotkey`.\n\n## External documentation\n\nTanStack Hotkeys supplies platform detection and keyboard shortcut formatting. Register behavior with `useHotkey` from `@tanstack/react-hotkeys` and label it with `Kbd`.\n\n- [TanStack Hotkeys](https://tanstack.com/hotkeys/latest/docs/reference)\n- [useHotkey](https://tanstack.com/hotkeys/latest/docs/framework/react/reference/functions/useHotkey)",
      },
    },
    layout: "centered",
  },
  tags: ["autodocs"],
} satisfies Meta<typeof Kbd>;

export default { ...meta, title: "Components/Kbd",  decorators: [(Story, context) => <ShowcaseProviders toast={false && context.viewMode !== "docs"}><ShowcaseSurface><Story /></ShowcaseSurface></ShowcaseProviders>] } satisfies Meta;

